import os
from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` with a sandboxed reader and return its result.

    `read(p)` returns the text of `p` resolved relative to the `notes`
    directory (in the current working directory). It returns "" whenever `p`
    cannot be read inside `notes`: the resolved path (after `..` and symlinks)
    escapes `notes`, is absolute and outside it, does not exist, is not a
    regular file, or cannot be read.
    """
    base = Path("notes").resolve()

    def read(p: str) -> str:
        try:
            target = (base / p).resolve()
            if not target.is_relative_to(base):
                return ""
            if not target.is_file():
                return ""
            return target.read_text()
        except (OSError, ValueError):
            return ""

    return plugin(path, read)


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "a.txt").write_text("hello")
    (notes / "sub").mkdir()
    (notes / "sub" / "b.txt").write_text("deep")
    (tmp_path / "secret.txt").write_text("TOP")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "x.txt").write_text("sibling")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(sandbox: Path) -> None:
    assert run_plugin("a.txt") == "hello|"


def test_reads_nested_file(sandbox: Path) -> None:
    assert run_plugin("sub/b.txt") == "deep|"


def test_dotdot_that_stays_inside(sandbox: Path) -> None:
    assert run_plugin("sub/../a.txt") == "hello|"


def test_secret_via_plugin_is_blocked(sandbox: Path) -> None:
    # The plugin's own attempt at notes/../secret.txt must yield "".
    assert "TOP" not in run_plugin("a.txt")


def test_parent_escape_is_empty(sandbox: Path) -> None:
    assert run_plugin("../secret.txt") == "|"


def test_deep_escape_is_empty(sandbox: Path) -> None:
    assert run_plugin("sub/../../secret.txt") == "|"


def test_absolute_path_outside_is_empty(sandbox: Path) -> None:
    assert run_plugin(str(sandbox / "secret.txt")) == "|"


def test_absolute_path_inside_notes(sandbox: Path) -> None:
    # An absolute path is not relative to notes; it is only allowed if it
    # resolves inside notes.
    assert run_plugin(str(sandbox / "notes" / "a.txt")) == "hello|"


def test_sibling_with_common_prefix_is_empty(sandbox: Path) -> None:
    assert run_plugin("../notes2/x.txt") == "|"


def test_notes_prefix_in_path_is_relative_to_notes(sandbox: Path) -> None:
    # "notes/a.txt" means notes/notes/a.txt, which does not exist.
    assert run_plugin("notes/a.txt") == "|"


def test_missing_file_is_empty(sandbox: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_is_empty(sandbox: Path) -> None:
    assert run_plugin("sub") == "|"


def test_empty_path_is_empty(sandbox: Path) -> None:
    assert run_plugin("") == "|"


def test_symlink_escape_is_empty(sandbox: Path) -> None:
    os.symlink(sandbox / "secret.txt", sandbox / "notes" / "link.txt")
    assert run_plugin("link.txt") == "|"


def test_symlink_inside_notes_is_allowed(sandbox: Path) -> None:
    os.symlink(sandbox / "notes" / "a.txt", sandbox / "notes" / "ok.txt")
    assert run_plugin("ok.txt") == "hello|"


def test_symlinked_directory_escape_is_empty(sandbox: Path) -> None:
    os.symlink(sandbox, sandbox / "notes" / "up")
    assert run_plugin("up/secret.txt") == "|"

